import{_ as e,a0 as o,w as r,s as u,ao as l,I as t,x as n,a1 as p,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Linux 中打扮你的冬季 Bash 提示符 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中打扮你的冬季 Bash 提示符 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中打扮你的冬季 Bash 提示符 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中打扮你的冬季 Bash 提示符 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20181211 Winterize your Bash prompt in Linux","title":"在 Linux 中打扮你的冬季 Bash 提示符","tag":"201901","desc":""},"relativePath":"201901/20181211 Winterize your Bash prompt in Linux.md","filePath":"[post].md"}'),d={name:"201901/20181211 Winterize your Bash prompt in Linux.md"};function g(k,s,m,b,f,h){const i=o("Link");return r(),u("div",null,[s[33]||(s[33]=l('<h1 id="在-linux-中打扮你的冬季-bash-提示符" tabindex="-1">在 Linux 中打扮你的冬季 Bash 提示符 <a class="header-anchor" href="#在-linux-中打扮你的冬季-bash-提示符" aria-label="Permalink to “在 Linux 中打扮你的冬季 Bash 提示符”">​</a></h1><blockquote><p>你的 Linux 終端可能支持 Unicode，那麼為何不利用它在提示符中添加季節性的圖標呢？</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/uploads/linux-toy-bash-prompt.png?itok=HK_kVn37" alt=""></p><p>歡迎再次來到 Linux 命令列玩具日曆的另一篇。如果這是你第一次訪問該系列，你甚至可能會問自己什麼是命令列玩具？我們對此比較隨意：它會是終端上有任何有趣的消遣，對於任何節日主題相關的還有額外的加分。</p><p>也許你以前見過其中的一些，也許你沒有。不管怎樣，我們希望你玩得開心。</p><p>今天的玩具非常簡單：它是你的 Bash 提示符。你的 Bash 提示符？是的！我們還有幾個星期的假期可以盯着它看，在北半球冬天還會再多幾周，所以為什麼不玩玩它。</p><p>目前你的 Bash 提示符號可能是一個簡單的美元符號（ <code>$</code>），或者更有可能是一個更長的東西。如果你不確定你的 Bash 提示符是什麼，你可以在環境變量 <code>$PS1</code> 中找到它。要查看它，請輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $PS1</span></span></code></pre></div><p>對於我而言，它返回：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[\\u@\\h \\W]\\$</span></span></code></pre></div>',10)),t("p",null,[s[1]||(s[1]=t("code",null,"\\u",-1)),s[2]||(s[2]=n("、",-1)),s[3]||(s[3]=t("code",null,"\\h",-1)),s[4]||(s[4]=n(" 和 ",-1)),s[5]||(s[5]=t("code",null,"\\W",-1)),s[6]||(s[6]=n(" 分別是用户名、主機名和工作目錄的特殊字符。你還可以使用其他一些符號。為了幫助構建你的 Bash 提示符，你可以使用 ",-1)),p(i,{href:"http://ezprompt.net/"},{default:a(()=>[...s[0]||(s[0]=[n("EzPrompt",-1)])]),_:1}),s[7]||(s[7]=n("，這是一個 ",-1)),s[8]||(s[8]=t("code",null,"PS1",-1)),s[9]||(s[9]=n(" 配置的在線生成器，它包含了許多選項，包括日期和時間、Git 狀態等。",-1))]),t("p",null,[s[11]||(s[11]=n("你可能還有其他變量來組成 Bash 提示符。對我來説，",-1)),s[12]||(s[12]=t("code",null,"$PS2",-1)),s[13]||(s[13]=n(" 包含了我命令提示符的結束括號。有關詳細信息，請參閲 ",-1)),p(i,{href:"https://access.redhat.com/solutions/505983"},{default:a(()=>[...s[10]||(s[10]=[n("這篇文章",-1)])]),_:1}),s[14]||(s[14]=n("。",-1))]),s[34]||(s[34]=l(`<p>要更改提示符，只需在終端中設置環境變量，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ PS1=&#39;\\u is cold: &#39;</span></span>
<span class="line"><span>jehb is cold:</span></span></code></pre></div><p>要永久設置它，請使用你喜歡的文本編輯器將相同的代碼添加到 <code>/etc/bashrc</code> 中。</p><p>那麼這些與冬季化有什麼關係呢？好吧，你很有可能有現代一下的機器，你的終端支持 Unicode，所以你不僅限於標準的 ASCII 字符集。你可以使用任何符合 Unicode 規範的 emoji，包括雪花 ❄、雪人 ☃ 或一對滑雪板 🎿。你有很多冬季 emoji 可供選擇。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>🎄 聖誕樹</span></span>
<span class="line"><span>🧥 外套</span></span>
<span class="line"><span>🦌 鹿</span></span>
<span class="line"><span>🧤 手套</span></span>
<span class="line"><span>🤶 聖誕夫人</span></span>
<span class="line"><span>🎅 聖誕老人</span></span>
<span class="line"><span>🧣 圍巾</span></span>
<span class="line"><span>🎿 滑雪者</span></span>
<span class="line"><span>🏂 滑雪板</span></span>
<span class="line"><span>❄ 雪花</span></span>
<span class="line"><span>☃ 雪人</span></span>
<span class="line"><span>⛄ 沒有雪的雪人</span></span>
<span class="line"><span>🎁 包裝好的禮物</span></span></code></pre></div><p>選擇你最喜歡的，享受冬天的歡樂。有趣的事實：現代文件系統也支持文件名中的 Unicode 字符，這意味着技術上你可以將你下個程序命名為 <code>❄❄❄❄❄.py</code>。只是説説，不要這麼做。</p><p>你有特別喜歡的命令列小玩具需要我介紹的嗎？這個系列要介紹的小玩具大部分已經有了落實，但還預留了幾個空位置。如果你有特別想了解的可以評論留言，我會查看的。如果還有空位置，我會考慮介紹它的。如果沒有，但如果我得到了一些很好的意見，我會在最後做一些有價值的提及。</p>`,7)),t("p",null,[s[16]||(s[16]=n("查看昨天的玩具，",-1)),p(i,{href:"https://opensource.com/article/18/12/linux-toy-snake"},{default:a(()=>[...s[15]||(s[15]=[n("在 Linux 終端玩貪吃蛇",-1)])]),_:1}),s[17]||(s[17]=n("，記得明天再來！",-1))]),s[35]||(s[35]=t("hr",null,null,-1)),t("p",null,[s[19]||(s[19]=n("via: ",-1)),p(i,{href:"https://opensource.com/article/18/12/linux-toy-bash-prompt"},{default:a(()=>[...s[18]||(s[18]=[n("https://opensource.com/article/18/12/linux-toy-bash-prompt",-1)])]),_:1})]),t("p",null,[s[24]||(s[24]=n("作者：",-1)),p(i,{href:"https://opensource.com/users/jason-baker"},{default:a(()=>[...s[20]||(s[20]=[n("Jason Baker",-1)])]),_:1}),s[25]||(s[25]=n(" 選題：",-1)),p(i,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[21]||(s[21]=[n("lujun9972",-1)])]),_:1}),s[26]||(s[26]=n(" 譯者：",-1)),p(i,{href:"https://github.com/geekpi"},{default:a(()=>[...s[22]||(s[22]=[n("geekpi",-1)])]),_:1}),s[27]||(s[27]=n(" 校對：",-1)),p(i,{href:"https://github.com/wxy"},{default:a(()=>[...s[23]||(s[23]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[30]||(s[30]=n("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[28]||(s[28]=[n("LCTT",-1)])]),_:1}),s[31]||(s[31]=n(" 原創編譯，",-1)),p(i,{href:"https://linux.cn/"},{default:a(()=>[...s[29]||(s[29]=[n("Linux中國",-1)])]),_:1}),s[32]||(s[32]=n(" 榮譽推出",-1))])])}const y=e(d,[["render",g]]);export{C as __pageData,y as default};
